    "overview": [
      "Orchid Classic Cruise offers a refined way to experience Ha Long Bay \u2013 Lan Ha Bay: wake up on the water, watch limestone islands pass by from the deck, and enjoy a slower perspective on northern Vietnam\u2019s most celebrated seascape. Lan Ha Bay, the quieter seascape along the eastern edge of C\u00e1t B\u00e0 Island, where limestone pinnacles, sheltered coves, and calm-water activities create a relaxed overnight-cruise rhythm.",
      "This overnight cruise is designed for travelers who want more than a quick sightseeing trip. The journey balances comfortable time onboard with curated bay exploration, giving you space to appreciate the scenery between activities. Available features described for this vessel include wellness facilities, a panoramic sundeck, a bar or lounge area. Individual cabin layouts and amenities may vary by category, so review the cabin description and inclusions before confirming your preferred option.",
      "Life on the bay is at its most memorable early in the morning and near sunset, when the light softens across the water and the cruise traffic is typically quieter. Keep a light layer handy for breezy decks, wear shoes with good grip for cave steps or tender transfers, and bring sun protection for outdoor activities. A waterproof pouch is useful for kayaking, while a small day bag makes embarkation and disembarkation easier."
    ],
    "lifeOnBoard": [
      "A multi-course Vietnamese and international menu featuring fresh sea catch prepared daily by onboard master chefs.",
      "Sunset cocktails on the sundeck, evening squid fishing, cooking demonstrations, and morning Tai Chi classes."
    ],
